def name_operands(region,function_address,operation):
    if region=='Action' and function_address==0xAE73:
        operation=operation.replace('(#AF14)','(@ActionLogRatioState.ShiftFraction)')
        operation=operation.replace('(#AF2F)','(@ActionLogRatioState.ShiftInteger)')
    return operation
